class CompatibilityScreen extends StatefulWidget{const CompatibilityScreen({super.key});@override State<CompatibilityScreen> createState()=>_CompatibilityScreenState();}
class _CompatibilityScreenState extends State<CompatibilityScreen>{String a='aries',b='libra';@override Widget build(BuildContext context){final x=zodiacById[a]!,y=zodiacById[b]!;return Scaffold(appBar:AppBar(title:const Text('Compatibility')),body:ListView(padding:const EdgeInsets.all(20),children:[const PageHeader('Two signs, many perspectives.',subtitle:'A reflective guide—not a relationship score.'),_selector('First sign',a,(v)=>setState(()=>a=v)),_selector('Second sign',b,(v)=>setState(()=>b=v)),Container(padding:const EdgeInsets.all(20),decoration:BoxDecoration(color:AppTheme.secondary,borderRadius:BorderRadius.circular(18)),child:Column(children:[Text(x.glyph+'  +  '+y.glyph,style:const TextStyle(fontSize:36,color:AppTheme.primary)),Text(x.name+' & '+y.name,style:Theme.of(context).textTheme.headlineMedium),Text('Traditional elements: '+x.element+' and '+y.element+'. Modalities: '+x.modality+' and '+y.modality+'.',textAlign:TextAlign.center)])),_section('Potential strengths','Different perspectives can create room for curiosity, learning and mutual support.'),_section('Possible friction','Different communication rhythms or priorities may call for patience and explicit conversations.'),_section('Conversation prompts','What helps each of you feel heard? Which shared routines would you like to build? What does support look like to each of you?'),const DisclaimerCard(),FilledButton.icon(onPressed:()async{await AstroRepository.instance.toggleSaved({'id':'compat-'+a+'-'+b,'sign':a+','+b,'title':x.name+' & '+y.name+' compatibility','body':'Traditional elements: '+x.element+' and '+y.element+'. Strengths: different perspectives can support curiosity and learning. Potential friction: communication rhythms may differ.','prompt':'What helps each of you feel heard?','content_type':'compatibility'});if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Compatibility saved locally.')));},icon:const Icon(Icons.bookmark_add_outlined),label:const Text('Save this pairing')),const InfoCard('Compatibility descriptions are symbolic traditions. Real relationships depend on people, communication and context.') ]));}
